import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('useRef', () => {
  test('Has an input with id "search"', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#search');
if (!input) throw new Error('No input with id "search" found');
if (input.tagName !== 'INPUT') throw new Error('Element should be an <input>');
  });

  test('Has a button with id "focus-btn"', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#focus-btn');
if (!btn) throw new Error('No button with id "focus-btn" found');
  });

  test('Clicking the button focuses the input', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#search');
const btn = root.querySelector('#focus-btn');
input.blur();
btn.click();
await tick();
if (document.activeElement !== input)
  throw new Error('Input should be focused after clicking the button');
  });
});
